import {fit,domain,norm,confirmedIds,blockedIds,resolvedMatches,upsertReports,reportStats,matchReport,nextAction} from './model.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('en-US');const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(n||0);
const today=()=>new Date().toLocaleDateString('en-CA');const uid=()=>crypto.randomUUID();const unique=a=>[...new Set(a.filter(Boolean))].sort();
const safeURL=s=>{try{const u=new URL(/^https?:\/\//i.test(s)?s:'https://'+s);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const link=(s,label)=>safeURL(s)?`<a href="${esc(safeURL(s))}" target="_blank" rel="noopener noreferrer">${esc(label||s)}</a>`:'Not supplied';
const badge=(s,cls='')=>`<span class="badge ${cls}">${esc(s)}</span>`;
const btn=(label,action,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':''}" data-action="${action}" ${attrs}>${label}</button>`;
const empty=(title,desc,action='')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`;
const opt=(values,selected='',first='All')=>`<option value="">${esc(first)}</option>`+values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const field=(label,name,value='',type='text',required=false)=>`<label>${esc(label)}<input name="${name}" value="${esc(value)}" type="${type}" ${required?'required':''}></label>`;
const select=(label,name,values,value='',first='Select…')=>`<label>${esc(label)}<select name="${name}">${opt(values,value,first)}</select></label>`;
const area=(label,name,value='',full=true)=>`<label class="${full?'full':''}">${esc(label)}<textarea name="${name}">${esc(value)}</textarea></label>`;
const navs=[['overview','Overview','overview'],['accounts','Team accounts','accounts'],['clients','CINC clients','accounts'],['map','Team map','map'],['hitlists','Hit lists','hitlists'],['campaigns','Campaigns','campaigns'],['resources','Sales resources','resources'],['events','Events & webinars','events'],['actions','Next actions','overview'],['imports','Data & reports','resources'],['settings','Settings','more']];
let data={teams:[],clients:[],matches:[],meta:{}},state,etag,view='overview',page=1,search='',filters={},scope='all',drawerId=null,drawerTab='brief',map=null,calendar=new Date(),reportPreview=null,resourceFilter='',saving=false;
let teamById=new Map(),clientById=new Map(),confirmed=new Set(),blocked=new Set();
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
async function api(path,options={}){const r=await fetch(path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});if(r.status===401&&path!='/api/login'){showLogin();throw new Error('Your session ended. Please sign in again.');}const result=await r.json();if(!r.ok)throw new Error(result.error||'Request failed');return {data:result,response:r};}
function showLogin(){$('#app').hidden=true;$('#login').hidden=false;}
function recalc(){confirmed=confirmedIds(data.matches,state);blocked=blockedIds(data.matches,state);}
async function load(){try{const [s,...ds]=await Promise.all([api('/api/state'),...['teams','clients','matches','meta'].map(k=>api('/api/data/'+k))]);state=s.data;etag=s.response.headers.get('ETag');['teams','clients','matches','meta'].forEach((k,i)=>data[k]=ds[i].data);teamById=new Map(data.teams.map(t=>[t.id,t]));clientById=new Map(data.clients.map(t=>[t.id,t]));recalc();$('#login').hidden=true;$('#app').hidden=false;nav();render();}catch(e){$('#login-error').textContent=e.message;}}
async function mutate(fn,description){if(saving)return toast('A save is in progress.');const next=structuredClone(state);fn(next);next.activity.unshift({id:uid(),at:new Date().toISOString(),text:description});next.activity=next.activity.slice(0,500);saving=true;$('#save-status').textContent='Saving…';try{const r=await api('/api/state',{method:'PUT',headers:{'If-Match':etag},body:JSON.stringify(next)});state=next;etag=r.response.headers.get('ETag');recalc();$('#save-status').textContent='All changes saved';render();if(drawerId)openTeam(drawerId,drawerTab);toast(description);return true;}catch(e){toast(e.message);$('#save-status').textContent='Not saved · reload to retry';return false;}finally{saving=false;}}
$('#signin').addEventListener('submit',async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#login-error').textContent='';try{await api('/api/login',{method:'POST',body:JSON.stringify({password:new FormData(e.target).get('password')})});e.target.reset();await load();}catch(err){$('#login-error').textContent=err.message;}finally{b.disabled=false;}});
function nav(){$('#nav').innerHTML=navs.map(([id,label,icon],i)=>`${i===8?'<div class="navdivider"></div>':''}<button class="navbtn ${id===view?'active':''}" data-action="go" data-view="${id}"><img src="/assets/${icon}.svg" alt="">${label}</button>`).join('');$('#mobile-nav').innerHTML=[['overview','Home','overview'],['accounts','Teams','accounts'],['campaigns','Campaigns','campaigns'],['resources','Resources','resources'],['more','More','more']].map(([id,label,icon])=>`<button data-action="${id==='more'?'more':'go'}" data-view="${id}" aria-current="${view===id||(id==='more'&&!['overview','accounts','campaigns','resources'].includes(view))?'page':'false'}" class="${view===id||(id==='more'&&!['overview','accounts','campaigns','resources'].includes(view))?'active':''}"><img src="/assets/${icon}.svg" alt="">${label}</button>`).join('');}
function go(id,opts={}){view=id;page=1;search='';filters={};scope='all';resourceFilter='';Object.assign(filters,opts);$('#dialog').close();closeDrawer();render();window.scrollTo(0,0);}
function head(title,desc,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,detail])=>`<div class="stat"><span>${label}</span><strong>${value}</strong><small>${detail}</small></div>`).join('')}</div>`;}
function panel(title,body,action=''){return `<section class="panel"><div class="panelhead"><h2>${title}</h2>${action}</div><div class="panelbody">${body}</div></section>`;}
function contact(t){return {...t,...state.contacts[t.id]};}function favorite(t,list){return (state.favorites[list]||[]).includes(t.id);}function isFav(t){return Object.values(state.favorites).some(ids=>ids.includes(t.id));}
function teamStatus(t){return confirmed.has(t.id)?badge('Client · Aug baseline','good'):blocked.has(t.id)?badge('Match under review','warn'):badge('Prospect');}
function rowsForTeams(teams){return teams.map(t=>{const c=contact(t),f=fit(t,state.settings);return `<tr><td><div><button class="link teamlink" data-action="team" data-id="${t.id}">${esc(t.name)}</button><small>${esc(t.city)}, ${esc(t.state)}</small></div><button class="heart ${isFav(t)?'on':''}" data-action="favorite" data-id="${t.id}" aria-label="Choose hit list for ${esc(t.name)}">${isFav(t)?'♥':'♡'}</button></td><td data-label="Brokerage">${esc(t.brokerage||'Unknown')}<small>${esc(t.company)}</small></td><td data-label="Technology">${esc(t.platform||'Unknown')}${t.fub?'<small>'+badge('Follow Up Boss','blue')+'</small>':''}</td><td data-label="Production">${t.sides==null?'—':fmt(t.sides)} sides<small>${t.volume==null?'Unknown volume':money(t.volume)} · ${t.agents==null?'?':fmt(t.agents)} agents</small></td><td data-label="Fit"><span class="score">${f.score}</span><small>${f.known}/3 inputs known</small></td><td data-label="Coverage">${teamStatus(t)}<small>${c.email?'Email':'No email'} · ${c.phone?'Phone':'No phone'}</small></td></tr>`;}).join('');}
function teamTable(teams){return teams.length?`<div class="tablewrap"><table class="account-table"><thead><tr><th>Team</th><th>Brokerage</th><th>Technology</th><th>Production</th><th>Pilot fit</th><th>Relationship & contact</th></tr></thead><tbody>${rowsForTeams(teams)}</tbody></table></div>`:empty('No teams match these filters','Try a different brokerage, platform, or location.');}
function pager(count){const pages=Math.max(1,Math.ceil(count/40));page=Math.min(page,pages);return `<div class="pagination"><span>${fmt(count)} records · Page ${page} of ${fmt(pages)}</span><div class="actions">${btn('Previous','page',`data-page="${page-1}" ${page===1?'disabled':''}`)}${btn('Next','page',`data-page="${page+1}" ${page===pages?'disabled':''}`)}</div></div>`;}
function filteredTeams(){let ts=data.teams.filter(t=>{const c=contact(t);return (!search||norm([t.name,t.city,t.state,t.leader,t.company,t.brokerage,t.website].join(' ')).includes(norm(search)))&&(!filters.brokerage||t.brokerage===filters.brokerage)&&(!filters.platform||t.platform===filters.platform)&&(!filters.state||t.state===filters.state)&&(!filters.size||t.size===filters.size)&&(!filters.production||Number(t.sides)>=Number(filters.production))&&(!filters.fub||t.fub)&&(!filters.list||t.lists.includes(filters.list))&&(!filters.status||(filters.status==='Prospects'?!blocked.has(t.id):filters.status==='Clients'?confirmed.has(t.id):blocked.has(t.id)&&!confirmed.has(t.id)))&&(scope!=='enrich'||!c.email||!c.phone)&&(scope!=='favorites'||(filters.list?favorite(t,filters.list):isFav(t)));});return ts.sort((a,b)=>filters.sort==='volume'?(b.volume||0)-(a.volume||0):filters.sort==='name'?a.name.localeCompare(b.name):fit(b,state.settings).score-fit(a,state.settings).score||(b.volume||0)-(a.volume||0));}
function teamFilters(){return `<div class="filters"><label class="search">Find a team<input id="search" placeholder="Team, city, leader, or website" value="${esc(search)}"></label>${[['Brokerage','brokerage',unique(data.teams.map(t=>t.brokerage))],['Website platform','platform',unique(data.teams.map(t=>t.platform))],['State','state',unique(data.teams.map(t=>t.state))],['Team size','size',unique(data.teams.map(t=>t.size))],['Relationship','status',['Prospects','Clients','Under review']]].map(([l,k,vs])=>`<label>${l}<select data-filter="${k}">${opt(vs,filters[k])}</select></label>`).join('')}<label>CRM<select data-filter="fub"><option value="">Any / unknown</option value="yes" ${filters.fub?'selected':''}>Follow Up Boss</option></select></label><label>Minimum sides<select data-filter="production">${opt(['25','50','100','250','500'],filters.production,'Any production')}</select></label><label>Sort<select data-filter="sort"><option value="fit">Pilot fit</option value="volume" ${filters.sort==='volume'?'selected':''}>Production volume</option><option value="name" ${filters.sort==='name'?'selected':''}>Team name</option></select></label>${btn('Clear','clear')}</div>`;}
function matchSummary(){const active=resolvedMatches(data.matches,state).filter(m=>m.status!=='rejected');const distinct=ms=>new Set(ms.map(m=>m.teamId||[m.rt_team,m.rt_city,m.rt_state].join('|'))).size;return {potential:distinct(active),links:active.length,domain:distinct(active.filter(m=>m.status==='verified-domain')),review:active.filter(m=>m.status==='review').length};}
function overlapPanel(){const m=matchSummary();return panel('Client overlap · match confidence',`<div class="row"><div><b>${fmt(m.potential)} potentially matched RealTrends teams</b><small>${fmt(m.links)} client-account links; multiple client records can point to one team.</small></div></div><div class="row"><div><b>${fmt(m.domain)} domain-verified teams</b><small>Exact website match reproduced in both source workbooks.</small></div></div><div class="row"><div><b>${fmt(confirmed.size)} verified teams in total</b><small>Domain-verified plus manually confirmed identities. Only these count toward verified penetration.</small></div></div><div class="row"><div><b>${fmt(m.review)} account links awaiting review</b><small>Includes missing website evidence, name matches, and state conflicts.</small></div>${btn('Review matches','match-view')}</div>`);}
function overview(){const overlap=matchSummary();const s=reportStats(state.reports),needs=data.teams.filter(t=>!contact(t).email||!contact(t).phone).length;const openTasks=state.tasks.filter(t=>t.status!=='Done');const priority=filteredTeams().filter(t=>!blocked.has(t.id)).slice(0,5);const denominator=data.teams.length;const penetration=denominator?(confirmed.size/denominator*100).toFixed(2):'0';return head('Growth, in focus.','Know the teams. Equip the conversation. See what moves the business.',btn('Print scorecard','print')+btn('Import sales report','go','data-view="imports"',true))+stats([['Ranked teams',fmt(denominator),'RealTrends · November 2026'],['Potentially matched teams',fmt(overlap.potential),`${fmt(overlap.domain)} domain-verified · ${fmt(overlap.links)} client-account links`],['Open pipeline',state.imports.length?money(s.pipeline):'—',state.imports.length?`${fmt(s.open)} linked open opportunities`:'Upload opportunity exports'],['Closed-won deals',state.imports.length?fmt(s.wins):'—',state.imports.length?`${money(s.revenue)} · linked deal value`:'Upload closed-deal exports']])+`<div class="grid"><div>${overlapPanel()}${panel('Priority teams',teamTable(priority),btn('View all','go','data-view="accounts"'))}${panel('Progress to goal',`<div class="progress-line"><span>${s.wins} linked wins</span><span>${fmt(state.settings.goal||250)} deal goal</span></div><div class="meter"><i style="width:${Math.min(100,s.wins/(state.settings.goal||250)*100)}%"></i></div><p class="formhint">${state.imports.length?`${s.appointments} appointments · ${s.opportunities} opportunities across imported snapshots.`:'Results appear after your first Salesforce report import. No sample revenue is included.'}</p>${btn('Review reports','go','data-view="imports"')}`)}</div><div>${panel('Where to focus next',`<div class="row"><div><b>${fmt(needs)} teams need enrichment</b><small>Missing email, phone, or both</small></div>${btn('Review','enrich')}</div><div class="row"><div><b>${resolvedMatches(data.matches,state).filter(m=>m.status==='review').length} matches to review</b><small>Keep uncertain links out of penetration</small></div>${btn('Review','match-view')}</div><div class="row"><div><b>${openTasks.length} open actions</b><small>Owners and follow-up dates</small></div>${btn('Open','go','data-view="actions"')}</div>`)}${panel('Marketing in motion',state.campaigns.length?state.campaigns.slice(0,4).map(c=>`<div class="row"><div><b>${esc(c.name)}</b><small>${esc(c.channel)} · ${c.teamIds.length} teams</small></div>${badge(c.status)}</div>`).join(''):empty('Your first campaign starts here','Build the audience, assign an owner, and track execution.',btn('Plan campaign','new-campaign')))}${panel('Recent activity',state.activity.length?state.activity.slice(0,4).map(a=>`<div class="row"><div><b>${esc(a.text)}</b><small>${new Date(a.at).toLocaleString()}</small></div></div>`).join(''):'<p>Saved activity will appear here.</p>')}</div></div><div class="notice">Potential overlap includes matches awaiting review. Verified penetration is ${penetration}% (${fmt(confirmed.size)} of ${fmt(denominator)} ranked teams), using verified identity links to the August 2026 roster. Neither figure is a live active-client count. Campaign membership records targeting—not proof that a person saw an ad.</div>`;}
function accounts(){const ts=filteredTeams();return head('Team accounts.','One account view across brokerage, website platform, and CRM.',btn('Export filtered teams','export-teams')+btn('Add to campaign','enroll-filtered','',true))+`<div class="tabs">${[['all','All teams'],['enrich','Needs enrichment'],['favorites','On a hit list']].map(([id,label])=>`<button data-action="scope" data-scope="${id}" class="${scope===id?'active':''}">${label}</button>`).join('')}</div>`+teamFilters()+pager(ts.length)+teamTable(ts.slice((page-1)*40,page*40));}
const clientRoles=['Advocate','Video case study','Client testimonial call','Speaker or webinar'];
const rolesFor=id=>state.clientEnablement?.[id]?.roles||[];
function clients(){const ms=resolvedMatches(data.matches,state);if(scope==='matches'){const rows=ms.filter(m=>(!search||norm(m.account+' '+m.rt_team).includes(norm(search)))&&(!filters.status||m.status===filters.status));return head('Review client matches.','Each decision preserves its evidence. Rejecting a link never deletes the client.',btn('All CINC clients','client-view'))+`<div class="filters"><label class="search">Search matches<input id="search" value="${esc(search)}" placeholder="Client or ranked team"></label><label>Status<select data-filter="status">${opt(['review','verified-domain','confirmed','rejected'],filters.status)}</select></label></div>`+pager(rows.length)+`<div class="tablewrap"><table><thead><tr><th>CINC client</th><th>Ranked team</th><th>Evidence</th><th>Decision</th></tr></thead><tbody>${rows.slice((page-1)*40,page*40).map(m=>`<tr><td>${esc(m.account)}<small>${esc(m.state)} · ${esc(m.domain)}</small></td><td><button class="link" data-action="team" data-id="${m.teamId}">${esc(m.rt_team)}</button><small>${esc(m.rt_city)}, ${esc(m.rt_state)}</small></td><td>${badge(m.method==='domain'?'Domain':'Name',m.status==='review'?'warn':'good')}<small>${esc(m.reason)}</small></td><td>${badge(m.status)}<div class="actions">${btn('Review','review-match',`data-id="${m.id}"`)}</div></td></tr>`).join('')}</tbody></table></div>`;}
const cs=data.clients.filter(c=>(!search||norm([c.name,c.domain,c.owner,c.state].join(' ')).includes(norm(search)))&&(!filters.role||rolesFor(c.id).includes(filters.role))&&(!filters.tenure||c.tenure===filters.tenure)&&(!filters.status||c.status===filters.status));return head('Your CINC relationships.','The complete client base, including clients outside the ranked team list.',btn('Review matches','match-view','',true))+stats([['Client records',fmt(data.clients.length),'August 2026 baseline'],['Potentially matched teams',fmt(matchSummary().potential),`${fmt(matchSummary().links)} client-account links`],['Verified ranked teams',fmt(confirmed.size),`${fmt(matchSummary().domain)} domain-verified teams`],['Account links to review',fmt(ms.filter(m=>m.status==='review').length),'Excluded from verified overlap']])+`<div class="filters"><label class="search">Find a client<input id="search" value="${esc(search)}" placeholder="Name, domain, owner, or state"></label><label>Client participation<select data-filter="role">${opt(clientRoles,filters.role)}</select></label><label>Tenure<select data-filter="tenure">${opt(unique(data.clients.map(c=>c.tenure)),filters.tenure)}</select></label><label>Source status<select data-filter="status">${opt(unique(data.clients.map(c=>c.status)),filters.status)}</select></label></div>`+pager(cs.length)+`<div class="tablewrap"><table class="account-table"><thead><tr><th>Client</th><th>Owner</th><th>Tenure</th><th>Source status</th><th>RealTrends relationship</th><th>Client participation</th></tr></thead><tbody>${cs.slice((page-1)*40,page*40).map(c=>{const links=ms.filter(m=>m.clientId===c.id&&m.status!=='rejected');return `<tr><td><div><button class="link teamlink" data-action="client" data-id="${c.id}">${esc(c.name)}</button><small>${esc(c.domain)}</small></div></td><td data-label="Owner">${esc(c.owner)}<small>${esc(c.state)}</small></td><td data-label="Tenure">${esc(c.tenure)}<small>${Number(c.tenureYears).toFixed(1)} years</small></td><td data-label="Status">${esc(c.status)}<small>${esc(c.substatus||'')} · Aug 2026</small></td><td data-label="Ranked team">${links.length?links.map(m=>badge(['verified-domain','confirmed'].includes(m.status)?'Verified link':'Under review',m.status==='review'?'warn':'good')).join(' '):badge('Not matched')}</td><td data-label="Client participation">${rolesFor(c.id).map(r=>badge(r,'good')).join(' ')||'<span class="muted">Not designated</span>'}</td></tr>`;}).join('')}</tbody></table></div>`;}
function hitlists(){return head('Your highest-priority teams.','Focus lists mirror the workbook tabs. Choose up to 100 teams within each focus.',btn('Browse all teams','go','data-view="accounts"'))+`<div class="cards">${(data.meta.listNames||[]).map(name=>{const n=(state.favorites[name]||[]).length,ts=data.teams.filter(t=>t.lists.includes(name));return `<article class="card"><span class="eyebrow">${['Keller Williams','Compass','REMAX','LPT Realty','eXp Realty','Berkshire Hathaway','Coldwell Banker','Real Broker'].includes(name)?'BROKERAGE':'PLATFORM / FOCUS'}</span><h2>${esc(name)}</h2><div class="listcount">${n}<small> / 100 selected</small></div><div class="meter"><i style="width:${n}%"></i></div><p>${fmt(ts.length)} teams in source tab</p><div class="actions">${btn('View focus','focus-list',`data-list="${esc(name)}"`)}${btn('View selected','selected-list',`data-list="${esc(name)}"`)}</div></article>`;}).join('')}</div>`;}
function campaigns(){return head('Every touch, connected.','Track audiences and execution across your five marketing channels.',btn('Plan campaign','new-campaign','',true))+`<div class="pilltabs">${['All','Direct Mail','YouTube','FB / Instagram','CTV','Outreach'].map(c=>`<button data-action="channel" data-channel="${c}" class="${(filters.channel||'All')===c?'active':''}">${c}</button>`).join('')}</div><div style="height:22px"></div>`+(state.campaigns.length?`<div class="cards">${state.campaigns.filter(c=>!filters.channel||c.channel===filters.channel).map(c=>{const s=reportStats(state.reports,new Set(c.teamIds));return `<article class="card"><div class="split-label">${badge(c.channel,'blue')}${badge(c.status)}</div><h2>${esc(c.name)}</h2><p>${esc(c.owner||'Owner unassigned')} · ${esc(c.start||'Date pending')}</p><div class="listcount">${fmt(c.teamIds.length)} <small>teams targeted</small></div><p>${s.appointments} appointments · ${s.wins} wins among members</p><small>Member outcomes are not causal attribution.</small><div class="actions">${btn('Open campaign','campaign',`data-id="${c.id}"`)}${btn('Edit','edit-campaign',`data-id="${c.id}"`)}</div></article>`;}).join('')}</div>`:empty('Build your first campaign','Start with a focus list, then record which teams are targeted and what happened.',btn('Plan campaign','new-campaign')));}
const resourceUse = r => r.format === 'Client testimonial call' ? 'Close a deal' : ({
  'Client Success Story':'Share customer proof', 'Client Advocate':'Find a client advocate',
  'Battle Card':'Handle a competitor', 'Talk Track':'Prepare for a conversation',
  'Outreach Cadence':'Start or follow up'
}[r.type] || 'Other');
function resources(){
  const all = state.resources;
  const rows = all.filter(r =>
    (!search || norm([r.title,r.body,r.brokerage,r.platform,r.location,resourceUse(r)].join(' ')).includes(norm(search))) &&
    (!filters.brokerage || r.brokerage === filters.brokerage) &&
    (!filters.platform || r.platform === filters.platform) &&
    (!filters.use || resourceUse(r) === filters.use) &&
    (!resourceFilter || r.type === resourceFilter));
  const groups = new Map();
  for(const r of rows){
    const key = r.brokerage || 'All brokerages';
    if(!groups.has(key)) groups.set(key,[]);
    groups.get(key).push(r);
  }
  const tabs = ['All','Talk Track','Client Success Story','Battle Card','Outreach Cadence','Client Advocate'];
  return head('Sales resources','Find the right resource by brokerage, platform, and sales situation.',btn('Add resource','new-resource','',true))+
    `<div class="filters"><label class="search">Search resources<input id="search" value="${esc(search)}" placeholder="Client, market, or topic"></label>
    <label>Brokerage<select data-filter="brokerage">${opt(unique(all.map(r=>r.brokerage)),filters.brokerage)}</select></label>
    <label>When to use<select data-filter="use">${opt(unique(all.map(resourceUse)),filters.use)}</select></label>
    <label>Platform<select data-filter="platform">${opt(unique([...all.map(r=>r.platform),...data.teams.map(t=>t.platform),'Follow Up Boss']),filters.platform)}</select></label></div>
    <div class="tabs">${tabs.map(t=>{const value=t==='All'?'':t;return `<button data-action="resource-type" data-type="${value}" class="${resourceFilter===value?'active':''}">${t}</button>`;}).join('')}</div>`+
    ([...groups].sort(([a, aItems], [b, bItems]) =>
      (resourceFilter ? 0 : bItems.length - aItems.length) || a.localeCompare(b)).map(([brokerage,items])=>panel(brokerage,`<div class="cards">${items.sort((a,b)=>resourceUse(a).localeCompare(resourceUse(b))||a.title.localeCompare(b.title)).map(resourceCard).join('')}</div>`,`<small>${items.length} resources</small>`).trim()).join('') || empty('No matching resources','Try another brokerage, use case, or search term.'));
}
function resourceCard(r,reasons=[]){return `<article class="card"><div class="split-label">${badge(r.format||r.type,'blue')}${badge(r.status,r.status==='Approved'?'good':'warn')}</div><h2>${esc(r.title)}</h2><p><strong>Use for</strong> ${esc(resourceUse(r))}</p><small>${esc([r.brokerage,r.platform,r.location,r.teamSize,r.production].filter(Boolean).join(' · ')||'All segments')}</small><p>${esc((r.body||'').slice(0,150))}</p>${reasons.length?`<small>${esc(reasons.join(' · '))}</small>`: ''}<div class="actions">${r.url?link(r.url,'Open resource'):''}${btn('Details / edit','edit-resource',`data-id="${r.id}"`)}</div></article>`;}
function events(){const month=calendar.toLocaleString('en-US',{month:'long',year:'numeric'});const y=calendar.getFullYear(),m=calendar.getMonth();const first=new Date(y,m,1),offset=first.getDay(),days=new Date(y,m+1,0).getDate();const cells=[];for(let i=0;i<Math.ceil((offset+days)/7)*7;i++){const d=i-offset+1,date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;cells.push(`<div class="${d<1||d>days?'outside':date===today()?'today':''}">${d>0&&d<=days?d:''}${state.events.filter(e=>e.date===date).map(e=>btn(esc(e.name),'event',`data-id="${e.id}"`)).join('')}</div>`);}return head('Be there before the conversation.','Plan event invitations, webinar messaging, and follow-up alongside your campaigns.',btn('Add event or webinar','new-event','',true))+`<div class="split-label"><h2>${month}</h2><div class="actions">${btn('Previous','month','data-delta="-1"')}${btn('Today','month','data-delta="0"')}${btn('Next','month','data-delta="1"')}</div></div><div class="calendar-month">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="dayname">${d}</div>`).join('')}${cells.join('')}</div><div style="height:24px"></div>`+panel('Upcoming & planned',state.events.length?state.events.slice().sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')).map(e=>`<div class="row"><div><b>${esc(e.name)}</b><small>${esc(e.date||'Date pending')} · ${esc(e.location||'Location pending')} · ${esc(e.type)}</small><small>${esc(e.focus||'Audience not assigned')}</small></div><div>${badge(e.status)} ${btn('Open','event',`data-id="${e.id}"`)}</div></div>`).join(''):empty('Your calendar is ready','Add the events and webinars you have confirmed. Dates will never be invented.',btn('Add event','new-event')));}
function actionsView(){const tasks=state.tasks.filter(t=>!filters.status||t.status===filters.status);const suggested=filteredTeams().filter(t=>!confirmed.has(t.id)&&!state.tasks.some(x=>x.teamId===t.id&&x.status!=='Done')).slice(0,6);return head('A clear next move.','Recommendations explain the reason. You decide what becomes an action.',btn('Add task','new-task','',true))+panel('Assigned actions',tasks.length?tasks.map(t=>`<div class="row"><div><b>${esc(t.title)}</b><small>${esc(teamById.get(t.teamId)?.name||'Workspace')} · ${esc(t.owner||'Unassigned')} · ${esc(t.due||'No due date')}</small>${badge(t.status)}</div><div class="actions">${btn('Edit','edit-task',`data-id="${t.id}"`)}${t.status!=='Done'?btn('Complete','complete-task',`data-id="${t.id}"`):''}</div></div>`).join(''):empty('No assigned actions yet','Accept a recommendation or create a task for your team.'))+panel('Suggested next actions',suggested.map(t=>`<div class="row"><div><b>${esc(nextAction(t,state,blocked))}</b><small>${esc(t.name)} · ${esc(t.brokerage)} · ${esc(t.platform||'Unknown platform')}</small><small>Reason: ${blocked.has(t.id)?'An unresolved customer link needs verification.':!contact(t).email&&!contact(t).phone?'The team has no usable contact channel.':'Coverage and approved-resource check.'}</small></div>${btn('Review','suggest-task',`data-id="${t.id}"`)}</div>`).join(''))+`<div class="notice">Recommendations are deterministic checks of your records. Live research, contact enrichment, and outbound agents are not connected yet.</div>`;}
function imports(){const s=reportStats(state.reports),unmatched=state.reports.filter(r=>!r.teamId);return head('Trust the numbers.','Upload Salesforce exports, review account matches, and keep the scorecard current.',btn('Download report template','template')+btn('Import report','import-report','',true))+stats([['Appointments',state.imports.length?fmt(s.appointments):'—','Linked unique appointment IDs'],['Opportunities',state.imports.length?fmt(s.opportunities):'—','Includes won and lost deals'],['Wins',state.imports.length?fmt(s.wins):'—','Unique closed-won opportunity IDs'],['Needs account match',fmt(unmatched.length),'Excluded from executive metrics']])+`<div class="grid equal">${panel('Source workbooks',`<div class="row"><div><b>RealTrends teams</b><small>${fmt(data.teams.length)} named team rows · imported ${esc(data.meta.loadedAt)}</small></div>${link(data.meta.teamSource,'Source')}</div><div class="row"><div><b>CINC client base</b><small>${fmt(data.clients.length)} accounts · ${esc(data.meta.clientSnapshot)} snapshot</small></div>${link(data.meta.clientSource,'Source')}</div><div class="row"><div><b>Matching evidence</b><small>${data.matches.length} candidate links · confidence retained</small></div>${btn('Review','match-view')}</div><p class="formhint">Source spreadsheets remain unchanged. One empty RealTrends row and six client summary rows were excluded.</p>`)}${panel('Import rules',`<p>Use CSV or XLSX. Every row requires a stable Salesforce Record ID and a snapshot date.</p><p>Appointment IDs are separate from opportunity IDs. Closed deals update the same opportunity—never count as a second opportunity.</p><p>Older snapshots cannot overwrite newer ones. Unmatched rows remain available for manual linking.</p><p class="formhint">Imports are incremental upserts. Absence from a file does not delete a prior record. Report totals reflect the latest imported state, not live Salesforce.</p>`)}</div>`+panel('Import history',state.imports.length?state.imports.map(i=>`<div class="row"><div><b>${esc(i.file)}</b><small>${esc(i.type)} · Snapshot ${esc(i.snapshot)} · ${i.count} rows · ${i.unmatched} unmatched at import</small></div><small>${new Date(i.at).toLocaleDateString()}</small></div>`).join(''):empty('No sales reports uploaded','Your baseline is ready. Add your first report to see pipeline and sales progress.'))+panel('Unmatched sales records',unmatched.length?unmatched.slice(0,100).map(r=>`<div class="row"><div><b>${esc(r.team||r.recordId)}</b><small>${esc(r.type)} · ${esc(r.state)} · ${esc(r.recordId)}</small></div>${btn('Link team','link-report',`data-id="${esc(r.recordId)}" data-type="${r.type}"`)}</div>`).join(''):'<p>No unmatched records.</p>');}
function settings(){return head('Keep the workspace intentional.','A transparent starting rubric. Adjust priorities with Sales and RevOps.')+`<form id="settings-form"><div class="grid equal">${panel('Growth target',field('Closed-won deal goal','goal',state.settings.goal||250,'number',true)+'<p class="formhint">This is a workspace goal across imported records. Period-specific forecasting comes after report coverage is established.</p>')}${panel('Pilot fit score · v1','<p>Agent count: up to 25 points at 10 agents.<br>Annual sides: up to 25 points at 100 sides.<br>Offering context: 30 for confirmed FUB, otherwise 20 for a known platform.<br>Strategic focus: 20 for a selected brokerage or platform.</p><p class="formhint">Missing inputs are explicitly shown. This prioritization hypothesis is not a trained propensity model. Engagement, contact coverage, and customer status are kept separate.</p>')}</div><div class="grid equal">${panel('Priority brokerages',`<div class="checklist">${unique(data.teams.map(t=>t.brokerage)).map(b=>`<label><input type="checkbox" name="priorityBrokerages" value="${esc(b)}" ${(state.settings.priorityBrokerages||[]).includes(b)?'checked':''}>${esc(b)}</label>`).join('')}</div>`)}${panel('Priority platforms',`<div class="checklist">${unique(data.teams.map(t=>t.platform)).map(b=>`<label><input type="checkbox" name="priorityPlatforms" value="${esc(b)}" ${(state.settings.priorityPlatforms||[]).includes(b)?'checked':''}>${esc(b)}</label>`).join('')}</div>`)}</div><button class="primary" type="submit">Save settings</button></form><div style="height:24px"></div>${panel('Connected capabilities','<div class="row"><b>Shared storage</b>'+badge('Connected','good')+'</div><div class="row"><b>Salesforce</b>'+badge('Report uploads','blue')+'</div><div class="row"><b>Outbound / enrichment agents</b>'+badge('Not connected','warn')+'</div><div class="row"><b>Access</b><span>Owner-private hosting + workspace password</span></div><p class="formhint">The shared password does not provide individual roles. Keep owner-private access while team permissions are being set up.</p>')}`;}
function mapView(){return head('See your market.','Explore teams by city, brokerage, and technology. Zoom into the relationships that matter.')+teamFilters()+`<div class="maplayout"><div id="map" class="map" aria-label="Interactive team location map"></div><aside class="mapaside" id="mapaside"></aside></div><div class="notice">Pins use city centroids, not business addresses. Multiple teams can share one pin. Coordinates: ${link('https://www.geonames.org/','GeoNames')}. Ambiguous city names and unlocated records remain flagged.</div>`;}
function mountMap(){const ts=filteredTeams(),located=ts.filter(t=>t.lat!=null);$('#mapaside').innerHTML=`<h2>${fmt(located.length)} mapped teams</h2><p class="formhint">${fmt(ts.length-located.length)} without a city match.<br>${fmt(located.filter(t=>t.geoAmbiguous).length)} have ambiguous city names.</p><p>Click a cluster to zoom. Click a city to see its teams.</p><h3>Largest concentrations</h3>`;if(!window.L){$('#map').innerHTML=empty('Map could not load','Refresh the page to try again.');return;}map=L.map('map',{zoomControl:true}).setView([38.8,-97],4);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);const cities=new Map();for(const t of located){const k=t.lat+','+t.lng;if(!cities.has(k))cities.set(k,[]);cities.get(k).push(t);}const clusters=L.markerClusterGroup({chunkedLoading:true,maxClusterRadius:45,iconCreateFunction:cluster=>L.divIcon({className:'city-pin',html:String(cluster.getAllChildMarkers().reduce((n,m)=>n+(m.options.teamCount||1),0)),iconSize:[40,40]})});for(const teams of cities.values()){const t=teams[0],icon=L.divIcon({className:'city-pin',html:String(teams.length),iconSize:[30,30]});const marker=L.marker([t.lat,t.lng],{icon,teamCount:teams.length});const content=document.createElement('div');content.innerHTML=`<b>${esc(t.city)}, ${esc(t.state)}</b><p>${teams.length} teams · city-level location</p>`+teams.slice(0,80).map(x=>`<button data-action="team" data-id="${x.id}">${esc(x.name)}</button>`).join('');marker.bindPopup(content);clusters.addLayer(marker);}map.addLayer(clusters);$('#mapaside').innerHTML+=[...cities.values()].sort((a,b)=>b.length-a.length).slice(0,12).map(c=>`<div class="row"><button class="link" data-action="zoom" data-lat="${c[0].lat}" data-lng="${c[0].lng}">${esc(c[0].city)}, ${esc(c[0].state)}</button>${badge(fmt(c.length))}</div>`).join('');}
function render(){if(!state)return;if(map){map.remove();map=null;}nav();$('#crumb').textContent=navs.find(n=>n[0]===view)?.[1]||'Overview';const renders={overview,accounts,clients,map:mapView,hitlists,campaigns,resources,events,actions:actionsView,imports,settings};$('#content').dataset.view=view;$('#content').innerHTML=(renders[view]||overview)();if(view==='map')mountMap();}
function closeDrawer(){$('#drawer').hidden=true;drawerId=null;document.body.style.overflow='';}
const brokerageKey = value => {
  const key = norm(value).replace(/[^a-z0-9]/g,'');
  return ({exprealty:'exp',realbroker:'realbrokerage',kw:'kellerwilliams',exit:'exitrealty',sothebys:'sothebysinternationalrealty',realtyonegroupcomplete:'realtyonegroup',independentother:'independent'})[key] || key;
};
function teamResources(team){
  const platforms = [team.platform, ...(team.fub ? ['Follow Up Boss','FUB'] : [])].map(norm);
  const marketKeys = [team.city,team.state,[team.city,team.state].filter(Boolean).join(', ')].map(norm);
  const matches = [];
  for(const resource of state.resources){
    if(resource.status === 'Retired') continue;
    const reasons = [];
    if(resource.brokerage){
      if(brokerageKey(resource.brokerage) !== brokerageKey(team.brokerage)) continue;
      reasons.push('Same brokerage');
    }
    if(resource.platform){
      if(!platforms.includes(norm(resource.platform))) continue;
      reasons.push('Same platform');
    }
    // Imported stories and references describe the client's market in this field.
    const descriptiveMarket = resource.sourceWorkbook || resource.id.startsWith('reference_');
    if(resource.location && !descriptiveMarket){
      if(!marketKeys.includes(norm(resource.location))) continue;
      reasons.push('Same market');
    }
    if(resource.teamSize && resource.teamSize !== team.size) continue;
    if(resource.production && (team.sides == null || Number(team.sides) < Number(resource.production))) continue;
    if(resource.teamSize) reasons.push('Same team size');
    if(resource.production) reasons.push('Meets production threshold');
    matches.push({resource,reasons});
  }
  return matches.sort((a,b)=>
    Number(b.resource.status==='Approved')-Number(a.resource.status==='Approved') ||
    b.reasons.length-a.reasons.length || a.resource.title.localeCompare(b.resource.title));
}
const teamResourceUses = ['Prepare for a conversation','Start or follow up','Share customer proof','Handle a competitor','Close a deal','Find a client advocate','Other'];
function matchedResourceSections(matches){
  return teamResourceUses.map(use=>{
    const items=matches.filter(({resource})=>resourceUse(resource)===use);
    if(!items.length) return '';
    return `<section class="detail-section"><h3>${esc(use)}</h3><div class="cards" style="grid-template-columns:1fr">${items.map(({resource,reasons})=>resourceCard(resource,reasons)).join('')}</div></section>`;
  }).join('');
}
function openTeam(id,tab='brief'){const t=teamById.get(id);if(!t)return toast('This team record is unavailable.');drawerId=id;drawerTab=tab;const c=contact(t),f=fit(t,state.settings),n=state.notes[id]||{},committee=n.committee||[];const matches=teamResources(t),ready=matches.filter(({resource})=>resource.status==='Approved');
let body='';if(tab==='brief')body=`<section class="detail-section"><div class="facts"><div><small>Licensed agents</small><strong>${t.agents==null?'Unknown':fmt(t.agents)}</strong></div><div><small>2025 sides</small><strong>${t.sides==null?'Unknown':fmt(t.sides)}</strong></div><div><small>2025 production</small><strong>${t.volume==null?'Unknown':money(t.volume)}</strong></div><div><small>Website platform</small><strong>${esc(t.platform||'Unknown')}</strong></div><div><small>Follow Up Boss</small><strong>${t.fub?'Confirmed in source':'Not confirmed'}</strong></div><div><small>Source</small>${link(data.meta.teamSource+'#gid=1660751206&range=A'+t.sourceRow+':N'+t.sourceRow,'Row '+t.sourceRow)}</div></div></section><section class="detail-section"><div class="split-label"><h3>Contact & enrichment</h3>${btn('Edit contact','contact',`data-id="${id}"`)}</div><p><b>${esc(c.leader||'Leader not identified')}</b><br>${esc(c.email||'Email needed')}<br>${esc(c.phone||'Phone needed')}</p>${t.website?link(t.website,'Visit team website'):badge('Website needed','warn')}<p class="evidence">${esc(c.verifiedAt?'Verified '+c.verifiedAt+' · '+(c.evidence||'Manual verification'):'Source-list contact details; verification pending.')}</p></section><section class="detail-section"><div class="split-label"><h3>Pilot fit · ${f.score}/100</h3>${badge(f.version,'blue')}</div><p>Agent count ${f.agents??'unknown'}/25 · Production ${f.production??'unknown'}/25 · Offering ${f.offering??'unknown'}/30 · Focus ${f.strategic}/20</p><p class="evidence">${f.known}/3 data inputs known. Missing values contribute no points and do not mean poor fit. Priorities are configurable in Settings.</p></section><section class="detail-section"><h3>Recommended next action</h3><p>${esc(nextAction(t,state,blocked))}</p>${btn('Assign action','suggest-task',`data-id="${id}"`,true)}</section><section class="detail-section"><h3>Buying committee</h3>${committee.length?committee.map(p=>`<div class="row"><div><b>${esc(p.name)} · ${esc(p.role)}</b><small>${esc(p.title)} · ${esc(p.relationship)}<br>Evidence: ${esc(p.evidence||'Not documented')}</small></div>${btn('Edit','edit-person',`data-id="${id}" data-person="${p.id}"`)}</div>`).join(''):'<p>Identify the team leader, decision maker, and operations or marketing evaluator. A contact name alone does not establish a relationship.</p>'}${btn('Add person','new-person',`data-id="${id}"`)}</section>`;
if(tab==='research')body=`<section class="detail-section"><h3>Account research & narrative</h3><p>Document observed facts and clearly label hypotheses. Approve the narrative before using it in outreach.</p>${badge(n.researchStatus||'Not started',n.researchStatus==='Approved'?'good':'warn')}<div class="research">${esc(n.research||'No research saved yet.')}</div><div class="actions">${btn('Edit research','research',`data-id="${id}"`)}${btn('Create discovery draft','draft',`data-id="${id}"`)}</div></section><section class="detail-section"><h3>Signals & evidence</h3>${state.signals.filter(s=>s.teamId===id).map(s=>`<div class="row"><div><b>${esc(s.title)}</b><small>${esc(s.date)} · ${esc(s.type)} · ${s.expires&&s.expires<today()?'Expired':'Current'}</small>${s.url?link(s.url,'Evidence'):''}<p>${esc(s.note||'')}</p></div></div>`).join('')||'<p>No validated signals recorded. Platform choice is context, not buying intent.</p>'}${btn('Add signal','new-signal',`data-id="${id}"`)}</section>`;
if(tab==='resources')body=`<section class="detail-section"><div class="split-label"><h3>Matched sales resources</h3>${btn('Add matched resource','team-resource',`data-id="${id}"`)}</div><p>${esc(t.brokerage||'Unknown brokerage')} · ${esc(t.platform||'Unknown website platform')}${t.fub?' · Follow Up Boss':''}</p></section>`+
  (matchedResourceSections(matches)||empty('No matching resources yet','Add a story, reference call, talk track, or other resource for this team.'));
if(tab==='brief' && ready.length){
  const counts=teamResourceUses.map(use=>[use,ready.filter(({resource})=>resourceUse(resource)===use).length]).filter(([,count])=>count);
  body+=`<section class="detail-section"><div class="split-label"><h3>Sales resources for this team</h3>${btn('View matched resources','team-tab',`data-id="${id}" data-tab="resources"`)}</div>${counts.map(([use,count])=>`<div class="row"><span>${esc(use)}</span><strong>${count}</strong></div>`).join('')}</section>`;
}
if(tab==='engagement')body=`<section class="detail-section"><h3>Campaign participation</h3>${state.campaigns.filter(x=>x.teamIds.includes(id)).map(x=>`<div class="row"><div><b>${esc(x.name)}</b><small>${esc(x.channel)} · ${esc(x.members?.[id]?.status||'Targeted')}</small></div>${btn('Open','campaign',`data-id="${x.id}"`)}</div>`).join('')||'<p>Not assigned to a campaign yet.</p>'}${btn('Add to campaign','enroll-team',`data-id="${id}"`)}</section><section class="detail-section"><h3>Engagement history</h3>${(n.touches||[]).map(x=>`<div class="row"><div><b>${esc(x.channel)} · ${esc(x.outcome)}</b><small>${esc(x.date)} · ${esc(x.owner)}</small><p>${esc(x.note)}</p></div></div>`).join('')||'<p>No recorded touches.</p>'}${btn('Log a touch','new-touch',`data-id="${id}"`)}</section><section class="detail-section"><h3>Sales outcomes</h3>${state.reports.filter(x=>x.teamId===id).map(x=>`<div class="row"><div><b>${esc(x.type)} · ${esc(x.stage||x.outcome||'Recorded')}</b><small>${esc(x.date)} · ${esc(x.owner)} · ${esc(x.recordId)}</small></div><span>${money(x.amount)}</span></div>`).join('')||'<p>No linked Salesforce records imported.</p>'}</section>`;
$('#drawer-content').innerHTML=`<div class="drawertop"><div><span class="eyebrow">TEAM PLAYBOOK</span>${teamStatus(t)}<h2 id="team-title">${esc(t.name)}</h2><p>${esc(t.city)}, ${esc(t.state)} · ${esc(t.brokerage)}</p></div><button class="close" data-action="close-drawer" aria-label="Close team">×</button></div><div class="tabs">${[['brief','Overview'],['research','Research & signals'],['resources','Sales resources'],['engagement','Engagement']].map(([k,label])=>`<button data-action="team-tab" data-tab="${k}" class="${tab===k?'active':''}">${label}</button>`).join('')}</div>${body}`;$('#drawer').hidden=false;document.body.style.overflow='hidden';$('#drawer-content').focus({preventScroll:true});}
