function campaignForm(id){const c=state.campaigns.find(c=>c.id===id)||{id:uid(),teamIds:[],members:{},status:'Draft'};modal(id?'Edit campaign':'Plan a campaign',form(field('Campaign name','name',c.name,'text',true)+select('Channel','channel',['Direct Mail','YouTube','FB / Instagram','CTV','Outreach'],c.channel)+field('Owner','owner',c.owner,'text',true)+select('Status','status',['Draft','Ready','Active','Complete','Paused'],c.status)+field('Start date','start',c.start,'date')+field('End date','end',c.end,'date')+field('Budget ($)','budget',c.budget,'number')+select('Linked event / webinar','eventId',state.events.map(x=>x.name),state.events.find(e=>e.id===c.eventId)?.name,'No event')+area('Campaign brief / message','brief',c.brief)+field('Creative or brief link','url',c.url,'url')),async fd=>{const v=Object.fromEntries(fd);if(!v.channel)throw Error('Choose a channel.');if(v.start&&v.end&&v.end<v.start)throw Error('End date must follow start date.');v.eventId=state.events.find(e=>e.name===v.eventId)?.id||'';await saveEntity('campaigns',{...c,...v},'Campaign saved');});}
