function audienceForm(campaignId,ids){modal('Add teams to a campaign',form(select('Campaign','campaign',state.campaigns.map(c=>c.name),state.campaigns.find(c=>c.id===campaignId)?.name)+`<div class="full notice">${ids.length} teams selected. Existing client matches and unresolved candidates are excluded from acquisition enrollment.</div>`,'Add teams'),async fd=>{const c=state.campaigns.find(c=>c.name===fd.get('campaign'));if(!c)throw Error('Create or choose a campaign first.');const eligible=ids.filter(id=>!blocked.has(id));const ok=await mutate(s=>{const x=s.campaigns.find(x=>x.id===c.id);x.teamIds=unique([...x.teamIds,...eligible]);},`${eligible.length} eligible teams added to campaign`);if(ok)$('#dialog').close();});}
function favoriteForm(id){const t=teamById.get(id);modal('Choose a Top 100 focus',`<p>${esc(t.name)}</p><p class="formhint">Lists mirror workbook tabs. Only the team’s source lists are available.</p><div class="checklist">${t.lists.map(l=>`<div class="row"><span>${esc(l)}<small>${(state.favorites[l]||[]).length}/100 selected</small></span>${btn(favorite(t,l)?'Remove':'Add','toggle-favorite',`data-id="${id}" data-list="${esc(l)}"`)}</div>`).join('')||'<p>This team does not belong to a segmented source tab.</p>'}</div>`);}
function contactForm(id){const c=contact(teamById.get(id));modal('Update contact details',form(field('Leader / primary contact','leader',c.leader)+field('Email','email',c.email)+field('Business phone','phone',c.phone)+field('Verified on','verifiedAt',c.verifiedAt,'date')+area('Verification evidence / source','evidence',c.evidence)+select('Enrichment status','enrichmentStatus',['Not started','Researching','Verified','Unable to find'],c.enrichmentStatus)),async fd=>{const v=Object.fromEntries(fd);if(v.enrichmentStatus==='Verified'&&(!v.evidence||!v.verifiedAt))throw Error('Add a verification date and evidence.');const ok=await mutate(s=>s.contacts[id]=v,'Contact details saved');if(ok)$('#dialog').close();});}
function personForm(id,personId){const p=(state.notes[id]?.committee||[]).find(p=>p.id===personId)||{id:uid()};modal('Buying committee contact',form(field('Name','name',p.name,'text',true)+field('Job title','title',p.title)+select('Buying role','role',['Decision Maker','Champion','Influencer','Technical Evaluator','Blocker','Unknown'],p.role)+select('Relationship strength','relationship',['Unknown','Identified','Contacted','Engaged','Trusted advocate'],p.relationship)+field('Email','email',p.email)+field('Last meaningful interaction','lastTouch',p.lastTouch,'date')+area('Evidence for role & relationship','evidence',p.evidence)),async fd=>{const v=Object.fromEntries(fd);if(!v.evidence&&['Engaged','Trusted advocate'].includes(v.relationship))throw Error('Document evidence for this relationship strength.');const ok=await mutate(s=>{s.notes[id]??={};s.notes[id].committee??=[];const a=s.notes[id].committee,i=a.findIndex(x=>x.id===p.id);if(i<0)a.push({...p,...v});else a[i]={...p,...v};},'Buying committee updated');if(ok)$('#dialog').close();});}
function researchForm(id,draft=false){const t=teamById.get(id),n=state.notes[id]||{};const text=draft?`FACTS FROM SOURCE\n${t.name} is listed with ${t.brokerage||'an unknown brokerage'} in ${t.city}, ${t.state}. Website platform: ${t.platform||'unknown'}. Follow Up Boss: ${t.fub?'confirmed in the FUB tab':'not confirmed'}.\nSource: ${data.meta.teamSource}\n\nDISCOVERY HYPOTHESIS — NOT VERIFIED\nExplore how the team acquires leads, follows up, and measures conversion. Do not assume dissatisfaction with its current platform.\n\nCONVERSATION OPENER\nHow are you connecting lead generation with agent follow-up today, and where would you most like to improve?\n\nOFFERING ANGLE TO VALIDATE\n${t.fub?'Discuss CINC’s offering for teams using Follow Up Boss; confirm current features with approved product materials.':'Explore whether CINC’s lead generation and follow-up capabilities fit the team’s stated goals.'}\n\nPROOF NEEDED\nApproved ${t.brokerage||'brokerage'} client story; approved ${t.platform||'platform'} comparison; permissioned client advocate.\n\nNEXT STEP\nVerify the decision maker and agree on a discovery meeting.\n\nThis is a rule-based draft assembled from source fields, not external AI research.`:n.research;modal(draft?'Review discovery draft':'Account research',form(area('Facts, hypotheses, narrative & citations','research',text)+select('Review status','researchStatus',['Draft','Approved'],draft?'Draft':n.researchStatus)+field('Reviewer','reviewer',n.reviewer)),async fd=>{const v=Object.fromEntries(fd);if(v.researchStatus==='Approved'&&!v.reviewer)throw Error('Name the reviewer before approving.');const ok=await mutate(s=>{s.notes[id]={...s.notes[id],...v,researchUpdated:today()};},'Research saved');if(ok)$('#dialog').close();});}
function resourceForm(id,teamId){const t=teamById.get(teamId),r=state.resources.find(x=>x.id===id)||{id:uid(),status:'Draft',brokerage:t?.brokerage||'',platform:t?.platform||''};modal(id?'Edit sales resource':'Add sales resource',form(field('Title','title',r.title,'text',true)+select('Resource type','type',['Talk Track','Client Success Story','Battle Card','Outreach Cadence','Client Advocate'],r.type)+select('Brokerage','brokerage',unique([...data.teams.map(t=>t.brokerage),...state.resources.map(r=>r.brokerage)]),r.brokerage,'Any brokerage')+select('Website platform / CRM','platform',unique(data.teams.map(t=>t.platform)).concat('Follow Up Boss'),r.platform,'Any platform')+field('Location (city or state)','location',r.location)+select('Team size','teamSize',unique(data.teams.map(t=>t.size)),r.teamSize,'Any size')+field('Minimum annual sides','production',r.production,'number')+field('Resource URL','url',r.url,'url')+area('Messaging / proof / advocate details','body',r.body)+select('Review status','status',['Draft','Approved','Retired'],r.status)+field('Reviewer / owner','reviewer',r.reviewer)+area('Evidence / client permission notes','evidence',r.evidence)),async fd=>{const v=Object.fromEntries(fd);if(!v.type)throw Error('Choose a resource type.');if(v.status==='Approved'&&(!v.reviewer||!v.evidence))throw Error('Approval requires a reviewer and evidence or client permission notes.');await saveEntity('resources',{...r,...v,updatedAt:today()},'Sales resource saved');});}
function eventForm(id){const e=state.events.find(x=>x.id===id)||{id:uid(),status:'Planning'};modal(id?'Edit event':'Add event or webinar',form(field('Event name','name',e.name,'text',true)+select('Type','type',['Brokerage event','Industry event','Tom Ferry event','CINC U','Workshop','Webinar','Other'],e.type)+field('Date','date',e.date,'date')+field('Location','location',e.location)+select('Status','status',['Planning','Confirmed','Complete','Cancelled'],e.status)+field('Owner','owner',e.owner)+select('Target focus','focus',data.meta.listNames||[],e.focus,'All / not assigned')+field('Event / registration URL','url',e.url,'url')+area('Messaging & activation plan','notes',e.notes)),async fd=>{await saveEntity('events',{...e,...Object.fromEntries(fd)},'Event saved');});}
function eventDetail(id){const e=state.events.find(e=>e.id===id);modal(e.name,`<p>${esc(e.date||'Date pending')} · ${esc(e.location)} · ${badge(e.status)}</p><p>${esc(e.notes||'No messaging plan yet.')}</p><p>Target focus: ${esc(e.focus||'Not assigned')}</p>${e.url?link(e.url,'Open event website'):''}<div class="actions">${btn('Edit event','edit-event',`data-id="${id}"`)}${btn('Plan campaign','new-campaign')}</div><h3 style="margin-top:24px">Linked campaigns</h3>${state.campaigns.filter(c=>c.eventId===id).map(c=>`<div class="row"><b>${esc(c.name)}</b>${btn('Open','campaign',`data-id="${c.id}"`)}</div>`).join('')||'<p>No linked campaigns yet.</p>'}`);}
function taskForm(id,teamId){const t=teamById.get(teamId),task=state.tasks.find(x=>x.id===id)||{id:uid(),teamId:teamId||'',title:t?nextAction(t,state,blocked):'',status:'Open'};modal('Assign next action',form(field('Action','title',task.title,'text',true)+field('Owner','owner',task.owner,'text',true)+field('Due date','due',task.due,'date')+select('Status','status',['Open','In progress','Snoozed','Done'],task.status)+area('Reason / context','note',task.note||task.notes|| (t?`${t.name} · ${t.brokerage} · ${t.platform||'Unknown platform'}`:''))),async fd=>{await saveEntity('tasks',{...task,...Object.fromEntries(fd)},'Action saved');});}
function signalForm(id){modal('Record a signal',form(field('Signal','title','','text',true)+select('Type','type',['Event attendance','Webinar attendance','Sales conversation','Growth / expansion','Leadership change','Platform change','Other'])+field('Observed date','date',today(),'date',true)+field('Expires on','expires','','date')+field('Evidence URL','url','','url',true)+area('Observed fact & commercial relevance','note')),async fd=>{const v=Object.fromEntries(fd);if(state.signals.some(s=>s.teamId===id&&norm(s.title)===norm(v.title)&&s.date===v.date))throw Error('This signal is already recorded.');await saveEntity('signals',{...v,id:uid(),teamId:id},'Signal recorded');});}
function touchForm(id){modal('Log an engagement',form(select('Channel','channel',['Call','Email','Direct Mail','Event','Webinar','Social','Other'])+select('Outcome','outcome',['Attempted','Delivered','Replied','Meeting booked','Attended','Not interested'])+field('Date','date',today(),'date',true)+field('Owner','owner','','text',true)+area('Notes / evidence','note')),async fd=>{const v=Object.fromEntries(fd);if(!v.channel||!v.outcome)throw Error('Choose a channel and outcome.');const ok=await mutate(s=>{s.notes[id]??={};s.notes[id].touches??=[];s.notes[id].touches.unshift({...v,id:uid()});},'Engagement recorded');if(ok)$('#dialog').close();});}
function reviewMatch(id){const m=resolvedMatches(data.matches,state).find(x=>x.id===id);modal('Review account identity',form(`<div class="full"><h3>${esc(m.account)}</h3><p>${esc(m.domain)} · ${esc(m.state)}</p><h3>${esc(m.rt_team)}</h3><p>${esc(m.rt_city)}, ${esc(m.rt_state)}</p><div class="notice">${esc(m.reason)}</div></div>`+select('Decision','status',['review','confirmed','rejected'],m.status==='verified-domain'?'confirmed':m.status)+field('Reviewer','reviewer',m.reviewer,'text',true)+area('Evidence / reason for decision','reason',m.reason)),async fd=>{const v=Object.fromEntries(fd);if(!v.reason)throw Error('Document the evidence for this decision.');const ok=await mutate(s=>s.matchDecisions[id]={...v,at:today()},'Client match decision saved');if(ok)$('#dialog').close();});}
function clientRolesForm(id){const c=clientById.get(id),saved=state.clientEnablement?.[id]||{};modal('Client participation',`<h3>${esc(c.name)}</h3><p>Select all that apply. You can update these at any time.</p>`+form(`<fieldset class="participation-options full"><legend>How this client can participate</legend>${clientRoles.map(role=>`<label><input type="checkbox" name="roles" value="${esc(role)}" ${rolesFor(id).includes(role)?'checked':''}><span>${esc(role)}</span></label>`).join('')}</fieldset>`+area('Participation notes','notes',saved.notes)),async fd=>{const ok=await mutate(s=>{s.clientEnablement??={};s.clientEnablement[id]={roles:fd.getAll('roles').filter(r=>clientRoles.includes(r)),notes:String(fd.get('notes')||''),updatedAt:new Date().toISOString()};},`Client participation updated: ${c.name}`);if(ok)clientDetail(id);});}
function clientDetail(id){const c=clientById.get(id);const ms=resolvedMatches(data.matches,state).filter(x=>x.clientId===id);modal('CINC client relationship',`<h3>${esc(c.name)}</h3><p>${esc(c.state)} · ${esc(c.owner)}</p>${link(c.domain,'Client website')}<div class="facts" style="margin:24px 0"><div><small>Tenure</small><strong>${Number(c.tenureYears).toFixed(1)} years</strong></div><div><small>Source status</small><strong>${esc(c.status)}</strong></div><div><small>T12 marketing spend</small><strong>${money(c.t12Marketing)}</strong></div></div><div class="notice">August 2026 snapshot. This does not verify current subscription status or permission to act as a reference.</div><h3>Client participation</h3><div class="client-roles">${rolesFor(id).map(r=>badge(r,'good')).join(' ')||'<p>No designations yet.</p>'}</div><div class="actions">${btn('Edit participation','client-roles',`data-id="${id}"`)}</div>${state.clientEnablement?.[id]?.notes?`<p style="white-space:pre-wrap">${esc(state.clientEnablement[id].notes)}</p>`:''}<h3 style="margin-top:24px">Client stories & resources</h3>${state.resources.filter(r=>r.clientIds?.includes(id)).map(resourceCard).join('')||'<p>No linked resources yet.</p>'}<h3 style="margin-top:24px">Ranked team links</h3>${ms.map(m=>`<div class="row"><div><b>${esc(m.rt_team)}</b>${badge(m.status)}</div>${btn('Review','review-match',`data-id="${m.id}"`)}</div>`).join('')||'<p>No ranked team link. This client remains in your full client base.</p>'}<div class="actions">${btn('Add advocate resource','new-resource')}</div>`);}
function memberForm(campaignId,teamId){const c=state.campaigns.find(x=>x.id===campaignId),m=c.members?.[teamId]||{};modal('Update campaign participation',form(select('Status','status',['Targeted','Scheduled','Sent / launched','Delivered (verified)','Responded','Meeting booked','Excluded'],m.status)+field('Date','date',m.date||today(),'date')+area('Evidence / outcome notes','note',m.note)),async fd=>{const v=Object.fromEntries(fd);if(v.status==='Delivered (verified)'&&!v.note)throw Error('Add delivery evidence.');const ok=await mutate(s=>{const x=s.campaigns.find(x=>x.id===campaignId);x.members??={};x.members[teamId]=v;},'Campaign participation updated');if(ok)$('#dialog').close();});}
function download(name,rows){const keys=Object.keys(rows[0]||{});const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'" ).replaceAll('"','""')+'"';const csv=[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);}
function exportTeams(ts,name='cinc-teams.csv'){download(name,ts.map(t=>{const c=contact(t);return {teamId:t.id,team:t.name,brokerage:t.brokerage,city:t.city,state:t.state,platform:t.platform,FUB:t.fub?'Confirmed':'Unknown',agents:t.agents,sides:t.sides,volume:t.volume,email:c.email,phone:c.phone,website:t.website,fit:fit(t,state.settings).score,relationship:confirmed.has(t.id)?'August client':blocked.has(t.id)?'Under review':'Prospect'};}));}
function importForm(){reportPreview=null;modal('Import a Salesforce report',`<form id="upload-form"><div class="fieldgrid">${select('Report type','type',['Appointments','Opportunities','Closed deals'],'Opportunities')}${field('Snapshot date','snapshot',today(),'date',true)}<label class="full drop">Choose CSV or XLSX<input type="file" name="file" accept=".csv,.xlsx" required><small>Maximum 10 MB. Map columns and review matches before saving. Closed-deal rows without a stage are treated as Closed Won.</small></label></div><div class="actions"><button type="submit" class="primary">Review columns</button></div></form>`,async fd=>{const file=fd.get('file');if(file.size>10e6)throw Error('Use a file smaller than 10 MB.');if(!window.XLSX)throw Error('Spreadsheet reader did not load. Refresh and try again.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});reportPreview={workbook,file:file.name,type:fd.get('type'),snapshot:fd.get('snapshot'),sheet:workbook.SheetNames[0]};columnForm();});}
function columnForm(){const p=reportPreview;const sheet=p.workbook.Sheets[p.sheet];const matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false});const hi=matrix.findIndex(r=>r.filter(Boolean).length>=3);if(hi<0)throw Error('No table found in this sheet.');p.headers=matrix[hi].map(String);p.raw=matrix.slice(hi+1).filter(r=>r.some(Boolean));if(p.raw.length>30000)throw Error('Import at most 30,000 rows at once.');const defaults={recordId:['recordid','opportunityid','appointmentid','activityid','id'],teamId:['teamid'],team:['team','teamname','accountname','account'],state:['state','billingstate'],website:['website','domain'],stage:['stage','opportunitystage'],amount:['amount','dealvalue'],date:['date','closedate','appointmentdate','activitydate'],owner:['owner','opportunityowner','assigned'],outcome:['outcome','status']};modal('Map your report columns',`<form><div class="fieldgrid"><label class="full">Workbook tab<select id="import-sheet">${p.workbook.SheetNames.map(s=>`<option ${s===p.sheet?'selected':''}>${esc(s)}</option>`).join('')}</select></label>${Object.entries(defaults).map(([key,aliases])=>{const guess=p.headers.find(h=>aliases.includes(norm(h)));return select(key==='recordId'?'Salesforce Record ID (required)':key,key,p.headers,guess,'Not supplied');}).join('')}</div><p class="formhint">${p.raw.length} rows. Use exported Team ID for the strongest match, or a unique domain, or exact team name + state abbreviation.</p><div class="actions"><button type="submit" class="primary">Preview matches</button></div></form>`,async fd=>{const mapping=Object.fromEntries(fd);if(!mapping.recordId)throw Error('Map a stable Salesforce Record ID.');p.rows=p.raw.map(r=>{const o={};for(const [k,h]of Object.entries(mapping))o[k]=h?String(r[p.headers.indexOf(h)]??'').trim():'';o.type=p.type==='Appointments'?'appointment':'opportunity';o.snapshot=p.snapshot;o.amount=Number(o.amount.replace(/[$,]/g,''))||0;if(norm(o.stage)==='closedwon')o.stage='Closed Won';if(norm(o.stage)==='closedlost')o.stage='Closed Lost';if(p.type==='Closed deals'&&!o.stage)o.stage='Closed Won';o.teamId=matchReport(o,data.teams);return o;});p.invalid=p.rows.filter(r=>!r.recordId);p.rows=p.rows.filter(r=>r.recordId);const keys=p.rows.map(r=>r.recordId);p.duplicates=keys.length-new Set(keys).size;previewImport();});}
function previewImport(){const p=reportPreview;const matched=p.rows.filter(r=>r.teamId).length;modal('Review before importing',`${stats([['Valid rows',fmt(p.rows.length),'Stable Record ID supplied'],['Matched',fmt(matched),'Linked to a ranked team'],['Unmatched',fmt(p.rows.length-matched),'Saved outside scorecard totals'],['Invalid / duplicates',`${p.invalid.length} / ${p.duplicates}`,'Resolve in the source file']])}<p>${esc(p.file)} · ${esc(p.type)} · Snapshot ${esc(p.snapshot)}</p><div class="tablewrap"><table><thead><tr><th>Record ID</th><th>Account</th><th>Match</th></tr></thead><tbody>${p.rows.slice(0,10).map(r=>`<tr><td>${esc(r.recordId)}</td><td>${esc(r.team||r.website)}</td><td>${r.teamId?esc(teamById.get(r.teamId).name):badge('Needs review','warn')}</td></tr>`).join('')}</tbody></table></div><div class="notice">An older snapshot cannot overwrite a newer record. Won deals update the same opportunity ID. This import does not delete records absent from the file.</div><div class="actions">${btn('Cancel','close-modal')}${btn('Confirm import','confirm-import',p.invalid.length||p.duplicates?'disabled':'',true)}</div>`);}
function linkReport(id,type){const r=state.reports.find(r=>r.recordId===id&&r.type===type);modal('Link a report record',form(`<div class="full"><p>${esc(r.team||r.recordId)} · ${esc(r.state)}</p><label>Search teams<input id="match-search" placeholder="Type a team name"></label><div id="match-options" class="checklist"></div><input name="teamId" id="match-team-id" type="hidden"></div>`,'Save team link'),async fd=>{const tid=fd.get('teamId');if(!teamById.has(tid))throw Error('Select a team first.');const ok=await mutate(s=>{s.reports.find(x=>x.recordId===id&&x.type===type).teamId=tid;},'Report account linked');if(ok)$('#dialog').close();});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){
case 'go':go(b.dataset.view);break;case 'more':modal('Your workspace',`<div style="display:grid;gap:8px">${navs.map(([v,l])=>btn(l,'go',`data-view="${v}"`)).join('')}</div>`);break;
case 'logout':await api('/api/logout',{method:'POST'});closeDrawer();showLogin();break;
case 'print':window.print();break;case 'close-modal':$('#dialog').close();break;case 'close-drawer':closeDrawer();break;
case 'page':page=Number(b.dataset.page);render();window.scrollTo(0,0);break;case 'scope':scope=b.dataset.scope;page=1;render();break;case 'clear':filters={};search='';page=1;render();break;
case 'enrich':go('accounts');scope='enrich';render();break;case 'match-view':go('clients');scope='matches';filters.status='review';render();break;case 'client-view':go('clients');break;
case 'team':$('#dialog').close();openTeam(id);break;case 'team-tab':openTeam(drawerId,b.dataset.tab);break;case 'client':clientDetail(id);break;case 'client-roles':clientRolesForm(id);break;
case 'favorite':favoriteForm(id);break;case 'toggle-favorite':{const list=b.dataset.list,ids=state.favorites[list]||[],remove=ids.includes(id);if(!remove&&ids.length>=100)return toast('This focus already has 100 teams. Remove one first.');const ok=await mutate(s=>s.favorites[list]=remove?ids.filter(x=>x!==id):[...ids,id],remove?'Removed from hit list':'Added to hit list');if(ok)favoriteForm(id);break;}
case 'focus-list':go('accounts',{list:b.dataset.list});break;case 'selected-list':go('accounts',{list:b.dataset.list});scope='favorites';render();break;
case 'new-campaign':campaignForm();break;case 'edit-campaign':campaignForm(id);break;case 'campaign':campaignDetail(id);break;
case 'enroll-filtered':audienceForm(null,filteredTeams().map(t=>t.id));break;case 'enroll-team':audienceForm(null,[id]);break;
case 'campaign-audience':modal('Choose a focus audience',form(select('Focus hit list','list',data.meta.listNames||[])) ,async fd=>{const ids=state.favorites[fd.get('list')]||[];if(!ids.length)throw Error('Select teams in this hit list first.');audienceForm(id,ids);});break;
case 'member':memberForm(id,b.dataset.team);break;case 'channel':filters.channel=b.dataset.channel==='All'?'':b.dataset.channel;render();break;
case 'new-resource':resourceForm();break;case 'edit-resource':resourceForm(id);break;case 'team-resource':resourceForm(null,id);break;case 'resource-type':resourceFilter=b.dataset.type;render();break;
case 'contact':contactForm(id);break;case 'new-person':personForm(id);break;case 'edit-person':personForm(id,b.dataset.person);break;case 'research':researchForm(id);break;case 'draft':researchForm(id,true);break;case 'new-signal':signalForm(id);break;case 'new-touch':touchForm(id);break;
case 'new-event':eventForm();break;case 'edit-event':eventForm(id);break;case 'event':eventDetail(id);break;case 'month':calendar=Number(b.dataset.delta)?new Date(calendar.getFullYear(),calendar.getMonth()+Number(b.dataset.delta),1):new Date();render();break;
case 'new-task':taskForm();break;case 'edit-task':taskForm(id);break;case 'suggest-task':taskForm(null,id);break;case 'complete-task':await mutate(s=>s.tasks.find(t=>t.id===id).status='Done','Action completed');break;
case 'review-match':reviewMatch(id);break;case 'export-teams':exportTeams(filteredTeams());break;case 'export-campaign':exportTeams(state.campaigns.find(c=>c.id===id).teamIds.map(x=>teamById.get(x)).filter(Boolean),'cinc-campaign-audience.csv');break;
case 'zoom':map?.setView([Number(b.dataset.lat),Number(b.dataset.lng)],11);break;
case 'template':download('salesforce-report-template.csv',[{recordId:'',teamId:'',team:'',state:'',website:'',stage:'',amount:'',date:'',owner:'',outcome:''}]);break;
case 'import-report':importForm();break;case 'confirm-import':{const p=reportPreview;if(!p||p.invalid.length||p.duplicates)return;const ok=await mutate(s=>{s.reports=upsertReports(s.reports,p.rows);s.imports.unshift({id:uid(),file:p.file,type:p.type,snapshot:p.snapshot,count:p.rows.length,unmatched:p.rows.filter(r=>!r.teamId).length,at:new Date().toISOString()});},'Sales report imported');if(ok){$('#dialog').close();reportPreview=null;}break;}
case 'link-report':linkReport(id,b.dataset.type);break;case 'choose-match':$('#match-team-id').value=id;$('#match-options').innerHTML=`<p>${esc(teamById.get(id).name)} selected.</p>`;break;
}}catch(err){toast(err.message);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;page=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;render();const input=$('#search');input?.focus();input?.setSelectionRange(pos,pos);},220);}if(e.target.id==='match-search'){const q=norm(e.target.value);$('#match-options').innerHTML=q.length>2?data.teams.filter(t=>norm(t.name).includes(q)).slice(0,12).map(t=>btn(esc(t.name+' · '+t.city+', '+t.state),'choose-match',`data-id="${t.id}"`)).join(''):'<p>Type at least 3 characters.</p>';}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;page=1;render();}if(e.target.id==='import-sheet'){reportPreview.sheet=e.target.value;columnForm();}});
document.addEventListener('submit',async e=>{if(e.target.id==='settings-form'){e.preventDefault();const fd=new FormData(e.target);await mutate(s=>s.settings={goal:Math.max(1,Number(fd.get('goal'))||250),priorityBrokerages:fd.getAll('priorityBrokerages'),priorityPlatforms:fd.getAll('priorityPlatforms')},'Workspace settings saved');}});
$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer'))closeDrawer();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#dialog').open)closeDrawer();if(e.key==='Tab'&&!$('#drawer').hidden&&!$('#dialog').open){const els=$$('#drawer button, #drawer a, #drawer input, #drawer textarea, #drawer select, #mobile-nav button');const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
api('/api/session').then(()=>load()).catch(()=>showLogin());
